import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [stats, setStats] = useState(null);

  useEffect(() => {
    const getData = () => axios.get('http://localhost:5000/api/dashboard-stats').then(res => setStats(res.data));
    getData();
    const interval = setInterval(getData, 5000); // Realtime
    return () => clearInterval(interval);
  }, []);

  if (!stats) return <div className="text-center p-10">Đang tải dữ liệu...</div>;

  return (
    <div className="max-w-5xl mx-auto p-8">
      <h1 className="text-3xl font-bold mb-8 text-gray-800">📊 Trung tâm dữ liệu (MongoDB Real-time)</h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-purple-500">
          <p className="text-gray-500 text-sm font-bold uppercase">Tổng Bài Tập</p>
          <p className="text-4xl font-extrabold text-gray-800 mt-2">{stats.total_exercises}</p>
        </div>
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-blue-500">
          <p className="text-gray-500 text-sm font-bold uppercase">Người Dùng (Ví)</p>
          <p className="text-4xl font-extrabold text-gray-800 mt-2">{stats.total_users}</p>
        </div>
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-green-500">
          <p className="text-gray-500 text-sm font-bold uppercase">Giao Dịch Đã Xử Lý</p>
          <p className="text-4xl font-extrabold text-gray-800 mt-2">{stats.total_exercises * 2 + 15} <span className="text-sm text-gray-400 font-normal">(Giả định)</span></p>
        </div>
      </div>

      <div className="glass-panel rounded-2xl overflow-hidden shadow-lg">
        <div className="bg-gradient-to-r from-gray-800 to-gray-900 px-6 py-4 border-b flex justify-between items-center">
          <h3 className="text-white font-bold text-lg">🏆 Bảng Xếp Hạng Uy Tín</h3>
          <span className="text-green-400 text-xs animate-pulse">● Cập nhật trực tiếp</span>
        </div>
        <table className="w-full">
          <thead className="bg-gray-50 text-gray-500 text-xs uppercase">
            <tr>
              <th className="py-4 px-6 text-left">Hạng</th>
              <th className="py-4 px-6 text-left">Địa chỉ Ví</th>
              <th className="py-4 px-6 text-center">Điểm Uy Tín</th>
              <th className="py-4 px-6 text-right">Danh hiệu</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {stats.top_creators.map((user, index) => (
              <tr key={index} className="hover:bg-blue-50 transition-colors">
                <td className="py-4 px-6 font-bold text-gray-600">
                  {index === 0 ? '🥇' : index === 1 ? '🥈' : index === 2 ? '🥉' : `#${index + 1}`}
                </td>
                <td className="py-4 px-6 font-mono text-indigo-600">{user.address}</td>
                <td className="py-4 px-6 text-center font-bold text-gray-800">{user.score}</td>
                <td className="py-4 px-6 text-right">
                  <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                    user.score > 100 ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-600'
                  }`}>
                    {user.score > 100 ? 'Elite Master' : 'Creator'}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Dashboard;
